const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
const eventName = sd.eventName || cfg.eventName;
// allowedChatId can be a comma list. The first one is the owner (gets reminders, can send emails).
const allowed = String(cfg.allowedChatId || '').split(',').map((s) => s.trim()).filter(Boolean);
const isAllowed = (id) => !allowed.length || allowed.includes(id);

// Called by this same workflow once per card found in a multi-card photo
if ($('When called with a card').isExecuted) {
  const inp = $('When called with a card').first().json;
  return [{ json: { route: 'text', fileId: null, contactId: null, chatId: String(inp.chatId || allowed[0] || ''), caption: '', text: String(inp.text || ''), eventName } }];
}

// Scheduled runs: Sunday = introductions, every morning = reminders
if (!$('Telegram Trigger').isExecuted) {
  if (!allowed[0]) return []; // nobody to send it to until allowedChatId is set
  if ($('Every Sunday at 6pm').isExecuted) return [{ json: { route: 'match', chatId: allowed[0] || '', eventName } }];
  return [{ json: { route: 'reminder', chatId: allowed[0] || '', eventName } }];
}

const upd = $('Telegram Trigger').first().json;

// A tap on a button under a contact card or a recap
if (upd.callback_query) {
  const cb = upd.callback_query;
  const chatId = String(cb.message?.chat?.id ?? cb.from?.id ?? '');
  if (!allowed.length || !isAllowed(chatId)) return [];
  const data = String(cb.data || '');
  const cut = data.indexOf('|');
  const action = cut > 0 ? data.slice(0, cut) : data;
  const value = cut > 0 ? data.slice(cut + 1) : '';
  const base = { queryId: cb.id, messageId: cb.message?.message_id ?? null, chatId, isOwner: !allowed.length || chatId === allowed[0], eventName };
  if (action === 'sendall') return [{ json: { route: 'sendall', date: value, ...base } }];
  if (action === 'intro') return [{ json: { route: 'intro', key: value, ...base } }];
  // "Edit this one" after /edit found several people: apply the change we kept
  if (action === 'ed') {
    const pend = (sd.pendingEdits || {})[chatId];
    if (!pend) return [{ json: { route: 'help', chatId } }];
    delete sd.pendingEdits[chatId];
    return [{ json: { route: 'update', contactId: value, text: pend.text, chatId, eventName } }];
  }
  return [{ json: { route: 'button', action, contactId: value, ...base } }];
}

const msg = upd.message || {};
const chatId = String(msg.chat?.id ?? '');

// Setup mode: until allowedChatId is filled in, every message just gets the guide with your chat ID
if (!allowed.length) return chatId ? [{ json: { route: 'help', chatId } }] : [];

// Not on the list: tell them politely instead of staying silent
if (!isAllowed(chatId)) return chatId ? [{ json: { route: 'denied', chatId } }] : [];

let route = 'help';
let fileId = null;
let contactId = null;
const text = msg.text || '';
const repliedTo = msg.reply_to_message?.text || '';
const idMatch = repliedTo.match(/ID: (\S+)/);

// A photo sent as a reply to a contact card = that person's picture
const photoId = msg.photo?.length
  ? msg.photo[msg.photo.length - 1].file_id
  : (msg.document && (msg.document.mime_type || '').startsWith('image/') ? msg.document.file_id : null);
if (photoId && idMatch) {
  return [{ json: { route: 'setphoto', chatId, contactId: idMatch[1], fileId: photoId, eventName } }];
}

// /event Web Summit Lisbon sets the event for new contacts
const evt = text.match(/^\/event(?:@\w+)?\s*([\s\S]*)$/i);
if (evt) {
  const name = evt[1].trim();
  if (name) sd.eventName = name;
  return [{ json: { route: 'event', chatId, eventName: name || eventName, changed: Boolean(name) } }];
}

// /recap: everyone you met today
if (/^\/recap(?:@\w+)?\b/i.test(text)) {
  return [{ json: { route: 'recap', chatId, isOwner: !allowed.length || chatId === allowed[0], eventName } }];
}

// /people [event]: everyone you met at an event (default: the current one)
const ppl = text.match(/^\/people(?:@\w+)?\s*([\s\S]*)$/i);
if (ppl) {
  return [{ json: { route: 'people', chatId, query: ppl[1].trim(), eventName } }];
}

// /top: your best open leads by score
if (/^\/top(?:@\w+)?\b/i.test(text)) {
  return [{ json: { route: 'top', chatId, eventName } }];
}

// /match: introductions worth making between people you know
if (/^\/match(?:@\w+)?\b/i.test(text)) {
  return [{ json: { route: 'match', chatId, eventName } }];
}

// /stats [event]: results of an event (default: the current one)
const stats = text.match(/^\/stats(?:@\w+)?\s*([\s\S]*)$/i);
if (stats) {
  return [{ json: { route: 'stats', chatId, query: stats[1].trim(), eventName } }];
}

// /nudges [days]: people you have not been in touch with (default 30 days)
const ndg = text.match(/^\/nudges?(?:@\w+)?\s*(\d*)/i);
if (ndg) {
  return [{ json: { route: 'nudges', chatId, days: Number(ndg[1]) || 30, eventName } }];
}

// /edit Sara phone +39...: change an existing contact, never create one
const ed = text.match(/^\/edit(?:@\w+)?\s*([\s\S]*)$/i);
if (ed) {
  const change = ed[1].trim();
  if (!change) return [{ json: { route: 'help', chatId, text } }];
  return [{ json: { route: 'editsearch', chatId, text: change, eventName } }];
}

// /search flutter: everyone who matches a skill, interest or need
const srch = text.match(/^\/search(?:@\w+)?\s*([\s\S]*)$/i);
if (srch) {
  const q = srch[1].trim();
  if (!q) return [{ json: { route: 'help', chatId, text } }];
  return [{ json: { route: 'ask', mode: 'search', chatId, question: q, eventName } }];
}

// Questions about your network: "/ask ...", "? ..." or "Who did I meet at ...?"
if (!idMatch) {
  const ask = text.match(/^(?:\/ask(?:@\w+)?|\?)\s*([\s\S]*)$/i);
  const looksLikeQuestion = /\?\s*$/.test(text)
    && /^(who|whom|which|what|how|when|where|list|show|find|do i|did i|have i|is there|are there)\b/i.test(text.trim());
  if (ask || looksLikeQuestion) {
    const question = (ask ? ask[1] : text).trim();
    // "/ask" on its own: show the guide with examples
    if (!question) return [{ json: { route: 'help', chatId, text } }];
    return [{ json: { route: 'ask', mode: 'ask', chatId, question, eventName } }];
  }
}

if (text && idMatch) {
  // Replying to a contact card = edit that contact
  route = 'update';
  contactId = idMatch[1];
} else if (msg.photo?.length) {
  route = 'photo';
  fileId = msg.photo[msg.photo.length - 1].file_id; // largest size
} else if (msg.document && (msg.document.mime_type || '').startsWith('image/')) {
  route = 'photo';
  fileId = msg.document.file_id;
} else if (msg.voice || msg.audio) {
  route = 'voice';
  fileId = (msg.voice || msg.audio).file_id;
} else if (text && !text.startsWith('/')) {
  route = 'text';
}

return [{ json: { route, fileId, contactId, chatId, caption: msg.caption || '', text, eventName } }];

// Pull the first JSON object out of whatever shape the OpenAI node returned
function findJson(v) {
  if (v == null) return null;
  if (typeof v === 'string') {
    const m = v.match(/\{[\s\S]*\}/);
    if (!m) return null;
    try { return JSON.parse(m[0]); } catch (e) { return null; }
  }
  if (Array.isArray(v)) {
    for (const x of v) { const r = findJson(x); if (r) return r; }
    return null;
  }
  if (typeof v === 'object') {
    if (v.text !== undefined) { const r = findJson(v.text); if (r) return r; }
    for (const k of ['output', 'content', 'message']) {
      if (v[k] !== undefined) { const r = findJson(v[k]); if (r) return r; }
    }
    return v;
  }
  return null;
}

const cfg = $('Config').first().json;
const route = $('Route message').first().json;
const ai = findJson($input.first().json) || {};
const s = (v) => (v == null ? '' : String(v).trim());

const c = {
  name: s(ai.name), role: s(ai.role), company: s(ai.company),
  email: s(ai.email).toLowerCase(), phone: s(ai.phone),
  linkedin: s(ai.linkedin), website: s(ai.website), context: s(ai.context),
};

// No website on the card? Use the email domain, unless it's a personal inbox
const personal = ['gmail.com','googlemail.com','yahoo.com','outlook.com','hotmail.com','live.com','icloud.com','me.com','proton.me','protonmail.com','aol.com','gmx.de','gmx.net','libero.it','web.de'];
if (!c.website && c.email.includes('@')) {
  const domain = c.email.split('@')[1];
  if (!personal.includes(domain)) c.website = domain;
}
if (c.website && !/^https?:\/\//i.test(c.website)) c.website = 'https://' + c.website;

const slug = (x) => x.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
if (!c.name && !c.company && !c.email && !c.phone) return []; // nothing readable, do not save a blank contact
const id = c.email || slug(`${c.name}-${c.company}`).slice(0, 40).replace(/-$/, '') || `contact-${Date.now()}`;
const notes = [route.caption, c.context].filter(Boolean).join(' | ');
// Captured from a screenshot of their LinkedIn profile: we already know their LinkedIn
const from_linkedin = ai.source === 'linkedin';

return [{ json: { id, captured_at: new Date().toISOString(), ...c, met_at: route.eventName || cfg.eventName, notes, from_linkedin } }];

