// Morning message: follow-ups that are due + people you have gone quiet with (your time zone)
const today = new Date().toLocaleDateString('en-CA', { timeZone: (() => { const z = $('Config').first().json.timeZone || 'UTC'; try { new Intl.DateTimeFormat('en-CA', { timeZone: z }); return z; } catch (e) { return 'UTC'; } })() });
const all = $input.all().map((i) => i.json).filter((r) => r && r.id);
const st = (r) => String(r.status || '').toLowerCase();
const lastTouch = (r) => {
  const ds = [String(r.captured_at || '').slice(0, 10), ...(String(r.notes || '').match(/\d{4}-\d{2}-\d{2}/g) || [])].filter(Boolean).sort();
  return ds[ds.length - 1] || '';
};
const daysSince = (d) => (d ? Math.floor((new Date(today + 'T00:00:00Z') - new Date(d + 'T00:00:00Z')) / 864e5) : 0);

const due = all
  .filter((r) => ['drafted', 'needs email'].includes(st(r)))
  .filter((r) => r.follow_up_on && String(r.follow_up_on) <= today);
const quiet = all
  .filter((r) => st(r) !== 'not relevant' && daysSince(lastTouch(r)) >= 30)
  .sort((a, b) => lastTouch(a).localeCompare(lastTouch(b)))
  .slice(0, 3);

if (!due.length && !quiet.length) return [];

const parts = [];
if (due.length) {
  const lines = due.map((r) => {
    const who = [r.name, r.company].filter(Boolean).join(' / ') || r.id;
    return st(r) === 'drafted'
      ? `- ${who}: draft "${r.email_subject}" is waiting in Gmail`
      : `- ${who}: still needs an email address`;
  });
  parts.push(`Follow-up time. ${due.length} ${due.length === 1 ? 'person is' : 'people are'} waiting on you:\n\n${lines.join('\n')}\n\nTap Send email on their card (or set status to "sent" in the sheet) to stop these reminders.`);
}
if (quiet.length) {
  const lines = quiet.map((r) => `- ${[r.name, r.company].filter(Boolean).join(' / ') || r.id}: no contact for ${daysSince(lastTouch(r))} days`);
  parts.push(`Keep in touch:\n${lines.join('\n')}\n\nSend /nudges for a reason to reach out and a ready message.`);
}

return [{ json: { message: parts.join('\n\n') } }];

