// Pull the first JSON object out of whatever shape the OpenAI node returned
function findJson(v) {
  if (v == null) return null;
  if (typeof v === 'string') {
    const m = v.match(/\{[\s\S]*\}/);
    if (!m) return null;
    try { return JSON.parse(m[0]); } catch (e) { return null; }
  }
  if (Array.isArray(v)) {
    for (const x of v) { const r = findJson(x); if (r) return r; }
    return null;
  }
  if (typeof v === 'object') {
    if (v.text !== undefined) { const r = findJson(v.text); if (r) return r; }
    for (const k of ['output', 'content', 'message']) {
      if (v[k] !== undefined) { const r = findJson(v[k]); if (r) return r; }
    }
    return v;
  }
  return null;
}

// WhatsApp needs the full international number, digits only
function waNumber(raw) {
  const s = String(raw ?? '').trim();
  const d = s.replace(/[^\d]/g, '');
  if (!d) return '';
  if (s.startsWith('+')) return d;
  if (d.startsWith('00')) return d.slice(2);
  if (d.length >= 11) return d;                        // already has a country code
  return '';
}

const contact = $('Match existing').first().json;
const cfg = $('Config').first().json;
const ai = findJson($input.first().json) || {};
const research = findJson($('Research person online').first().json) || {};
const list = (v) => (Array.isArray(v) ? v.filter(Boolean) : []);
// Only borrow person details from research when we know who the person is
const known = Boolean(contact.name);

const due = new Date();
due.setDate(due.getDate() + (Number(cfg.followUpDays) || 3));

const temperature = ai.temperature || 'warm';
const rawScore = Number(ai.score);
const lead_score = Number.isFinite(rawScore) ? Math.max(0, Math.min(100, Math.round(rawScore))) : ({ hot: 70, warm: 50, cold: 30 }[temperature] || 50);

const out = {
  ...contact,
  role: contact.role || (known ? research.current_role || '' : ''),
  company: contact.company || research.current_company || '',
  linkedin: contact.linkedin || (known ? research.linkedin_url || '' : ''),
  website: contact.website || research.company_website || '',
  personal_website: known ? research.personal_website || '' : '',
  location: research.location || '',
  headline: research.headline || '',
  background: research.background || '',
  recent_activity: research.recent_activity || '',
  talking_points: list(research.talking_points).join(' | '),
  sources: list(research.sources).join(' '),
  research_confidence: research.confidence || 'none',
  summary: ai.summary || '',
  company_insight: ai.company_insight || '',
  temperature,
  lead_score,
  score_reason: ai.score_reason || '',
  next_step: ai.next_step || '',
  email_subject: ai.subject || '',
  email_body: ai.body || '',
  whatsapp_message: ai.whatsapp || '',
  follow_up_on: due.toISOString().slice(0, 10),
};

// No em or en dashes anywhere in what we save or send
for (const k of Object.keys(out)) {
  if (typeof out[k] === 'string') out[k] = out[k].replace(/[–—]/g, '-');
}

// Links for the WhatsApp and LinkedIn buttons (always valid URLs)
const firstName = String(out.name || '').split(' ')[0];
const waText = encodeURIComponent((out.whatsapp_message || `Hi ${firstName}, great meeting you at ${out.met_at}!`).slice(0, 400));
const num = waNumber(out.phone);
out.whatsapp_url = num ? `https://wa.me/${num}?text=${waText}` : `https://wa.me/?text=${waText}`;
const li = String(out.linkedin || '').trim();
if (/^https?:\/\//i.test(li)) {
  out.linkedin_open_url = li;
} else if (li) {
  let p = li.replace(/^(www\.)?linkedin\.com\//i, '').replace(/^\/+/, '');
  if (!p.includes('/')) p = 'in/' + p;
  out.linkedin_open_url = 'https://www.linkedin.com/' + p.split('/').map(encodeURIComponent).join('/');
} else {
  const q = [out.name, out.company].filter(Boolean).join(' ') || out.email || 'contact';
  out.linkedin_open_url = 'https://www.linkedin.com/search/results/people/?keywords=' + encodeURIComponent(q);
}

return [{ json: out }];

const r = $('Prepare follow-up').first().json;
const route = $('Route message').first().json;
const draftId = $('Create Gmail draft').isExecuted ? ($('Create Gmail draft').first().json.id || '') : '';

// Picture: keep a personal photo; otherwise the card photo you just sent
const cardPhoto = route.route === 'photo' ? (route.fileId || '') : '';
const photo_file_id = r.photo_file_id || cardPhoto;
const photo_source = r.photo_source || (cardPhoto ? 'card' : '');
// Company logo from the website domain
let host = '';
try { host = r.website ? new URL(r.website).hostname : ''; } catch (e) { host = ''; }
const logo_url = host ? `https://www.google.com/s2/favicons?domain=${host}&sz=128` : '';

const row = { ...r, gmail_draft_id: draftId, status: r.email ? 'drafted' : 'needs email', photo_file_id, photo_source, logo_url };

// Keep only the sheet columns, in header order
const cols = ["id", "captured_at", "name", "role", "company", "email", "phone", "linkedin", "website", "personal_website", "location", "headline", "background", "recent_activity", "talking_points", "sources", "research_confidence", "met_at", "notes", "summary", "company_insight", "temperature", "lead_score", "score_reason", "next_step", "email_subject", "email_body", "whatsapp_message", "gmail_draft_id", "follow_up_on", "status", "photo_file_id", "photo_source", "logo_url"];
return [{ json: Object.fromEntries(cols.map((c) => [c, row[c] ?? ''])) }];

parameters.text:
={{ (() => {
  const r = $('Build CRM row').first().json;
  const p = $('Prepare follow-up').first().json;
  const NL = String.fromCharCode(10);
  const esc = (s) => String(s ?? '').trim().replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const section = (title, lines) => ['<b>' + title + '</b>'].concat(lines).join(NL);
  const name = r.name || r.company || 'New contact';
  const sub = [r.role, r.company && r.company !== name ? r.company : ''].filter(Boolean).join(' · ');
  const points = String(r.talking_points || '').split('|').map((t) => t.trim()).filter(Boolean);
  const linkedinLine = r.linkedin ? 'LinkedIn: ' + esc(r.linkedin) : (p.from_linkedin ? 'LinkedIn: profile link not confirmed yet, the LinkedIn button opens a search for them' : '');
  const contact = [
    r.email ? 'Email: ' + esc(r.email) : '',
    r.phone ? 'Phone: ' + esc(r.phone) : '',
    linkedinLine,
    r.personal_website ? 'Website: ' + esc(r.personal_website) : (r.website ? 'Website: ' + esc(r.website) : ''),
  ].filter(Boolean);
  const blocks = [];

  blocks.push([
    '<b>' + (p.seen_before ? 'Updated' : 'Saved') + ': ' + esc(name) + '</b>',
    sub ? esc(sub) : '',
    r.headline ? '<i>' + esc(r.headline) + '</i>' : '',
    p.seen_before ? '<i>Already in your list since ' + esc(p.seen_before) + '</i>' : '',
  ].filter(Boolean).join(NL));

  blocks.push([
    '<b>Lead score:</b> ' + esc(r.lead_score) + '/100 · ' + esc(r.temperature),
    r.score_reason ? '<i>' + esc(r.score_reason) + '</i>' : '',
    '<b>Research confidence:</b> ' + esc(r.research_confidence),
  ].filter(Boolean).join(NL));

  if (r.summary) blocks.push(section('Why they matter', [esc(r.summary)]));
  if (points.length) blocks.push(section('What to talk about', points.map((t) => '• ' + esc(t))));
  if (r.next_step) blocks.push(section('Next step', [esc(r.next_step)]));
  if (contact.length) blocks.push(section('Contact', contact));
  blocks.push(section('Follow-up', [
    r.email ? 'Gmail draft ready: "' + esc(r.email_subject) + '"' : 'No email yet. Reply to this card with their email and I will add it.',
    'Reminder on ' + esc(r.follow_up_on) + ' if it is still unsent.',
  ]));
  blocks.push(['<i>Tap a button below, or reply to this card to change anything.</i>', 'ID: ' + esc(r.id)].join(NL));
  return blocks.join(NL + NL);
})() }}

