const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clean = (s) => String(s || '').replace(/[–—]/g, '-').trim();
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const packed = $('Pack contacts').first().json;
const ai = findJson($input.first().json) || {};
const results = Array.isArray(ai.results) ? ai.results.filter((r) => r && clean(r.name)) : [];
const answer = clean(ai.answer);

let message;
if (!answer && !results.length) {
  message = esc(packed.count
    ? 'I could not answer that right now (the AI did not respond). Try again in a minute.'
    : 'Your contact list is still empty. Send me a card, a voice note or a text after your next conversation.');
} else if (packed.mode === 'search') {
  const title = `<b>Search: ${esc(packed.question)}</b>`;
  if (results.length) {
    const blocks = results.slice(0, 20).map((r, i) => {
      const sub = [clean(r.role), clean(r.company)].filter(Boolean).join(' · ');
      return `<b>${i + 1}. ${esc(clean(r.name))}</b>${sub ? '\n' + esc(sub) : ''}${clean(r.why) ? '\n<i>' + esc(clean(r.why)) + '</i>' : ''}`;
    });
    while (blocks.length > 1 && blocks.join('\n\n').length > 3500) blocks.pop(); // stay under Telegram's 4096 limit
    const more = results.length > blocks.length ? `\n\n...and ${results.length - blocks.length} more. Try a narrower search.` : '';
    message = `${title}\n${results.length} ${results.length === 1 ? 'person' : 'people'} found\n\n${blocks.join('\n\n')}${more}`;
  } else {
    message = `${title}\n\n${esc(answer || 'Nobody in your network matches that yet.')}`;
  }
} else {
  message = esc(answer.slice(0, 3800));
}

// Saved photos of the people found (max 5), matched back to the sheet by name
const rows = $('Read all for question').all().map((i) => i.json).filter((r) => r && r.id);
const photos = [];
