    }
  }
}

return [{ json: { message, photos } }];

// Everyone you met today (your time zone)
const tz = (() => { const z = $('Config').first().json.timeZone || 'UTC'; try { new Intl.DateTimeFormat('en-CA', { timeZone: z }); return z; } catch (e) { return 'UTC'; } })();
const route = $('Route message').first().json;
