const ai = findJson($input.first().json) || {};
const q = String(ai.name_query || '').trim();
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const tokens = norm(q).split(/[^a-z0-9]+/).filter(Boolean);
const rows = $('Read all for edit').all().map((i) => i.json).filter((r) => r && r.id);

if (!tokens.length) {
  return [{ json: { mode: 'none', message: 'Tell me who to edit, for example: /edit Sara phone +1234567890' } }];
}
const hits = rows.filter((r) => { const n = norm(r.name); return n && tokens.every((t) => n.includes(t)); });

if (!hits.length) {
  return [{ json: { mode: 'none', message: `I could not find anyone called "${q}" in your contacts, so I did not change or create anything.` } }];
}
if (hits.length === 1) {
  return [{ json: { mode: 'one', contactId: String(hits[0].id) } }];
}

// Several people match: keep the change until the user taps one
const sd = $getWorkflowStaticData('global');
sd.pendingEdits = sd.pendingEdits || {};
sd.pendingEdits[route.chatId] = { text: route.text, at: new Date().toISOString() };

const label = (r) => `${r.name}${r.role || r.company ? ', ' + [r.role, r.company].filter(Boolean).join(' at ') : ''}${r.met_at ? ` (met at ${r.met_at})` : ''}`;
return hits.slice(0, 8).map((r, i) => ({ json: {
  mode: 'many',
  contactId: String(r.id),
  message: `${i === 0 ? `I found ${hits.length} people matching "${q}". Tap the one you mean:\n\n` : ''}${label(r)}`,
} }));

// Best open leads first. Older rows without a score get one from their temperature.
const done = ['sent', 'not relevant', 'meeting booked', 'replied'];
const rows = $input.all().map((i) => i.json)
  .filter((r) => r && r.id && !done.includes(String(r.status || '').toLowerCase()));
const scoreOf = (r) => {
  const n = Number(r.lead_score);
  if (r.lead_score !== '' && Number.isFinite(n)) return { s: n, est: false };
  return { s: ({ hot: 70, warm: 50, cold: 30 }[r.temperature] || 40), est: true };
};

if (!rows.length) {
  return [{ json: { message: 'No open leads right now. Everyone is either sent, booked or marked not relevant.' } }];
}

const top = rows.map((r) => ({ r, ...scoreOf(r) })).sort((a, b) => b.s - a.s).slice(0, 5);
const lines = top.map(({ r, s, est }, i) => {
  const who = [r.name || r.company || r.id, r.role && r.company ? `${r.role} at ${r.company}` : (r.company || r.role)].filter(Boolean).join(', ');
  const state = String(r.status || '').toLowerCase() === 'drafted' ? 'draft ready' : (r.status || 'saved');
  return `${i + 1}. ${who}: ${est ? '~' : ''}${s}/100 (${state})${r.score_reason ? `\n   ${r.score_reason}` : ''}${r.next_step ? `\n   Next: ${r.next_step}` : ''}`;
});

return [{ json: { message: [`Your top ${top.length} open leads:`, '', ...lines, '', top.some((t) => t.est) ? '~ = estimated from temperature (saved before scoring existed).' : ''].filter((l, i, a) => l !== '' || (i > 0 && i < a.length - 1)).join('\n').trim() } }];

// What did each event bring you?
const route = $('Route message').first().json;
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const st = (r) => String(r.status || '').toLowerCase();
const wasSent = (r) => ['sent', 'meeting booked', 'replied'].includes(st(r)) || /follow-up email sent/.test(String(r.notes || ''));
const scoreOf = (r) => { const n = Number(r.lead_score); return r.lead_score !== '' && Number.isFinite(n) ? n : ({ hot: 70, warm: 50, cold: 30 }[r.temperature] || 40); };
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id);

if (!rows.length) return [{ json: { message: 'No contacts saved yet. Send me a card, a voice note or a text after your next conversation.' } }];

const groups = {};
for (const r of rows) { const e = r.met_at || 'No event'; (groups[e] = groups[e] || []).push(r); }
const names = Object.keys(groups);
const target = route.query || route.eventName || '';
const key = names.find((k) => norm(k) === norm(target)) || (target ? names.find((k) => norm(k).includes(norm(target))) : null);

const lines = [];
if (key) {
  const list = groups[key];
  const n = (f) => list.filter(f).length;
  const avg = Math.round(list.reduce((a, r) => a + scoreOf(r), 0) / list.length);
  const best = [...list].sort((a, b) => scoreOf(b) - scoreOf(a)).slice(0, 3).map((r) => `${r.name || r.company || r.id} (${scoreOf(r)})`).join(', ');
  lines.push(
    `${key}: ${list.length} ${list.length === 1 ? 'person' : 'people'}`,
    `Hot ${n((r) => r.temperature === 'hot')} | Warm ${n((r) => r.temperature === 'warm')} | Cold ${n((r) => r.temperature === 'cold')} | Avg lead score ${avg}`,
    `Emails sent ${n(wasSent)} | Meetings booked ${n((r) => st(r) === 'meeting booked')} | Drafts waiting ${n((r) => st(r) === 'drafted')} | Missing email ${n((r) => st(r) === 'needs email')}`,
    `Best leads: ${best}`,
  );
} else {
  if (target) lines.push(`No contacts saved for "${target}" yet.`);
}

const others = names.filter((k) => k !== key)
  .map((k) => `- ${k}: ${groups[k].length} ${groups[k].length === 1 ? 'person' : 'people'}, ${groups[k].filter(wasSent).length} emailed`);
if (others.length) lines.push('', 'Other events:', ...others, '', 'Details for another event: /stats Web Summit');

return [{ json: { message: lines.join('\n') } }];

// People you have not been in touch with for N days (last touch = newest date on the row)
// Max 3 people so the message (with WhatsApp links) stays under Telegram's 4096 characters
const days = Number($('Route message').first().json.days) || 30;
const st = (r) => String(r.status || '').toLowerCase();
const lastTouch = (r) => {
  const ds = [String(r.captured_at || '').slice(0, 10), ...(String(r.notes || '').match(/\d{4}-\d{2}-\d{2}/g) || [])].filter(Boolean).sort();
  return ds[ds.length - 1] || '';
};
const daysSince = (d) => (d ? Math.floor((Date.now() - new Date(d + 'T00:00:00Z')) / 864e5) : 0);
const cut = (s, n) => String(s ?? '').slice(0, n);

const quiet = $input.all().map((i) => i.json)
  .filter((r) => r && r.id && st(r) !== 'not relevant' && daysSince(lastTouch(r)) >= days)
  .sort((a, b) => lastTouch(a).localeCompare(lastTouch(b)))
  .slice(0, 3);

if (!quiet.length) {
  return [{ json: { none: true, message: `Nobody has gone quiet: you have been in touch with everyone in the last ${days} ${days === 1 ? 'day' : 'days'}.` } }];
}

const people = quiet.map((r) => ({
  id: String(r.id), name: r.name || r.company || r.id, role: r.role, company: r.company,
  met_at: r.met_at, days_quiet: daysSince(lastTouch(r)), status: r.status, phone: String(r.phone ?? ''),
  recent_activity: cut(r.recent_activity, 300), talking_points: cut(r.talking_points, 300), notes: cut(r.notes, 300), summary: cut(r.summary, 200),
}));
return [{ json: { none: false, days, people, peopleText: JSON.stringify(people) } }];

// Pull the first JSON object out of whatever shape the OpenAI node returned
function findJson(v) {
  if (v == null) return null;
  if (typeof v === 'string') {
    const m = v.match(/\{[\s\S]*\}/);
    if (!m) return null;
    try { return JSON.parse(m[0]); } catch (e) { return null; }
  }
  if (Array.isArray(v)) {
    for (const x of v) { const r = findJson(x); if (r) return r; }
    return null;
  }
  if (typeof v === 'object') {
    if (v.text !== undefined) { const r = findJson(v.text); if (r) return r; }
    for (const k of ['output', 'content', 'message']) {
      if (v[k] !== undefined) { const r = findJson(v[k]); if (r) return r; }
    }
    return v;
  }
  return null;
}

// WhatsApp needs the full international number, digits only
function waNumber(raw) {
  const s = String(raw ?? '').trim();
  const d = s.replace(/[^\d]/g, '');
  if (!d) return '';
  if (s.startsWith('+')) return d;
  if (d.startsWith('00')) return d.slice(2);
  if (d.length >= 11) return d;
  return '';
}

const picked = $('Pick quiet contacts').first().json;
const ai = findJson($input.first().json) || {};
const byId = Object.fromEntries((Array.isArray(ai.items) ? ai.items : []).map((x) => [String(x.id), x]));
const clean = (s) => String(s || '').replace(/[–—]/g, '-').trim();

const blocks = picked.people.map((p, i) => {
  const s = byId[p.id] || {};
  const who = [p.name, p.company && p.company !== p.name ? p.company : ''].filter(Boolean).join(', ');
  const lines = [`${i + 1}. ${who}: ${p.days_quiet} ${p.days_quiet === 1 ? 'day' : 'days'} quiet`];
  if (s.reason) lines.push(`   Why now: ${clean(s.reason)}`);
  if (s.message) {
    lines.push(`   Message: "${clean(s.message)}"`);
    const num = waNumber(p.phone);
    lines.push(`   WhatsApp: https://wa.me/${num}?text=${encodeURIComponent(clean(s.message))}`.replace('wa.me/?', 'wa.me/?'));
  }
  return lines.join('\n');
});

const header = `People you have not been in touch with for ${picked.days}+ ${picked.days === 1 ? 'day' : 'days'}:`;
const footer = Object.keys(byId).length ? '' : '\n(The AI did not answer, so no suggestions this time. Try /nudges again in a minute.)';
return [{ json: { message: `${header}\n\n${blocks.join('\n\n')}${footer}` } }];

// Everyone who could be introduced (not 'not relevant', not you)
const cfg = $('Config').first().json;
const norm = (s) => String(s || '').toLowerCase().trim();
const cut = (s, n) => String(s ?? '').slice(0, n);
const rows = $input.all().map((i) => i.json)
  .filter((r) => r && r.id && String(r.status || '').toLowerCase() !== 'not relevant' && norm(r.name) !== norm(cfg.yourName))
  .slice(-40);

if (rows.length < 2) {
  return [{ json: { enough: false, message: 'I need at least 2 people in your network to suggest introductions.' } }];
}
const people = rows.map((r) => ({
  id: String(r.id), name: r.name, role: r.role, company: r.company, headline: cut(r.headline, 120),
  summary: cut(r.summary, 200), notes: cut(r.notes, 200), background: cut(r.background, 200),
}));
return [{ json: { enough: true, peopleText: JSON.stringify(people) } }];

