const ai = findJson($input.first().json) || {};
const rows = $('Read all for match').all().map((i) => i.json).filter((r) => r && r.id);
const byId = Object.fromEntries(rows.map((r) => [String(r.id), r]));
const ms = (Array.isArray(ai.matches) ? ai.matches : [])
  .filter((m) => byId[m.a_id] && byId[m.b_id] && m.a_id !== m.b_id)
  .slice(0, 3);

if (!ms.length) {
  return [{ json: { hasMatch: false, message: 'No strong introductions in your network right now. Add more people and try /match again.' } }];
}

// Keep each pair under a short key so the button fits Telegram's 64-byte limit
const sd = $getWorkflowStaticData('global');
sd.matches = sd.matches || {};
const old = Object.keys(sd.matches);
if (old.length > 20) for (const k of old.slice(0, old.length - 20)) delete sd.matches[k];
const stamp = Date.now().toString(36);
const label = (r) => [r.name || r.company, r.role && r.company ? `${r.role} at ${r.company}` : (r.company || r.role)].filter(Boolean).join(', ');

return ms.map((m, i) => {
  const key = `${stamp}${i}`;
  sd.matches[key] = { a: String(m.a_id), b: String(m.b_id), why: m.why };
  return { json: {
    hasMatch: true,
    key,
    message: `${i === 0 ? `Introductions worth making (${ms.length}):\n\n` : ''}${i + 1}. ${label(byId[m.a_id])}\n   + ${label(byId[m.b_id])}\n   Why: ${String(m.why).replace(/[–—]/g, '-')}`,
  } };
});

// The two people from the suggestion that was tapped
const route = $('Route message').first().json;
const sd = $getWorkflowStaticData('global');
const m = (sd.matches || {})[route.key];
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id);
if (!m) return [{ json: { ok: false, message: 'That suggestion expired. Send /match for fresh ideas.' } }];
const a = rows.find((r) => String(r.id) === m.a);
const b = rows.find((r) => String(r.id) === m.b);
if (!a || !b) return [{ json: { ok: false, message: 'One of those people is not in your sheet anymore.' } }];

const pick = (r) => ({ name: r.name || r.company, role: r.role, company: r.company, email: r.email, met_at: r.met_at,
  summary: String(r.summary || '').slice(0, 200), notes: String(r.notes || '').slice(0, 200) });
return [{ json: { ok: true, why: m.why, a: pick(a), b: pick(b), pairText: JSON.stringify({ why: m.why, person_a: pick(a), person_b: pick(b) }) } }];

