const pair = $('Pick intro pair').first().json;
const ai = findJson($input.first().json) || {};
const clean = (s) => String(s || '').replace(/[–—]/g, '-').trim();
const subject = clean(ai.subject) || `Intro: ${pair.a.name} and ${pair.b.name}`;
const body = clean(ai.body);
const missing = [pair.a, pair.b].filter((p) => !p.email).map((p) => p.name);
const hasEmails = missing.length === 0 && Boolean(body);

let message = body
  ? `Intro: ${pair.a.name} + ${pair.b.name}\n\nSubject: ${subject}\n\n${body}`
  : 'I could not write the introduction right now (the AI did not answer). Try the button again in a minute.';
if (body && !hasEmails) message += `\n\nNo Gmail draft: ${missing.join(' and ')} ${missing.length === 1 ? 'has' : 'have'} no email yet. Copy the text above, or add the email with /edit.`;

return [{ json: { hasEmails, to: `${pair.a.email}, ${pair.b.email}`, subject, body, message } }];

