// One card: continue as before. Several: one text per card, each run through the full pipeline.
const ai = findJson($input.first().json) || {};
let list = Array.isArray(ai.contacts) ? ai.contacts : (ai.name !== undefined ? [ai] : []);
list = list.filter((c) => c && (c.name || c.company || c.email || c.phone));

if (list.length <= 1) return [{ json: { many: false, ...(list[0] || {}) } }];

const route = $('Route message').first().json;
return list.map((c) => {
  const parts = [
    `Met ${c.name || 'someone'}`,
    [c.role, c.company].filter(Boolean).join(' at '),
    c.email && `email ${c.email}`,
    c.phone && `phone ${c.phone}`,
    c.website && `website ${c.website}`,
    c.linkedin && `LinkedIn ${c.linkedin}`,
    c.context,
    route.caption && `Notes: ${route.caption}`,
  ].filter(Boolean);
  return { json: { many: true, count: list.length, chatId: route.chatId, name: c.name || c.company || 'someone', text: parts.join(', ') } };
});

// Save the photo you sent as this person's picture
const route = $('Route message').first().json;
const row = { ...($input.first()?.json || {}) };
delete row.row_number;
if (!row.id) return [{ json: { id: '', message: 'I could not find that contact anymore, so the photo was not saved.' } }];

row.photo_file_id = route.fileId;
row.photo_source = 'person';
const stamp = new Date().toISOString().slice(0, 10);
row.notes = [row.notes, `${stamp}: photo added`].filter(Boolean).join(' | ');
return [{ json: row }];

// Everyone you met at an event, complete and in the order you met them
const route = $('Route message').first().json;
const esc = (s) => String(s ?? '').trim().replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id);
if (!rows.length) return [{ json: { message: 'No contacts saved yet. Send me a card, a voice note or a text after your next conversation.' } }];

const groups = {};
for (const r of rows) { const e = r.met_at || 'No event'; (groups[e] = groups[e] || []).push(r); }
const names = Object.keys(groups);
const target = route.query || route.eventName || '';
const key = names.find((k) => norm(k) === norm(target)) || (target ? names.find((k) => norm(k).includes(norm(target))) : null);

if (!key) {
  return [{ json: { message: `No contacts saved for "${esc(target)}".\n\n<b>Your events</b>\n${names.map((k) => `• ${esc(k)} (${groups[k].length})`).join('\n')}\n\nTry: /people ${esc(names[0])}` } }];
}

const list = [...groups[key]].sort((a, b) => String(a.captured_at).localeCompare(String(b.captured_at)));
const shown = list.slice(0, 30);
const lines = shown.map((r, i) => {
  const sub = [r.role, r.company && r.company !== r.name ? r.company : ''].filter(Boolean).join(' · ');
  const meta = [r.status, r.lead_score !== '' && r.lead_score != null ? `score ${r.lead_score}` : '', r.photo_source === 'person' ? 'has photo' : ''].filter(Boolean).join(' · ');
  return [`<b>${i + 1}. ${esc(r.name || r.company || r.id)}</b>`, sub ? esc(sub) : '', meta ? `<i>${esc(meta)}</i>` : ''].filter(Boolean).join('\n');
});
while (lines.length > 1 && lines.join('\n\n').length > 3300) lines.pop(); // stay under Telegram's 4096 limit
const more = list.length > lines.length ? `\n\n...and ${list.length - lines.length} more.` : '';
const others = names.filter((k) => k !== key).map((k) => `${esc(k)} (${groups[k].length})`).join(', ');

return [{ json: { message: `<b>People you met at ${esc(key)}</b>\n${list.length} ${list.length === 1 ? 'person' : 'people'}\n\n${lines.join('\n\n')}${more}${others ? `\n\n<i>Other events: ${others}</i>` : ''}` } }];
